class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        offset = 1800
        size = 3601
        dp = [[-1] * 2 for _ in range(size)]

        for num in nums:
            new_dp = [row[:] for row in dp]

            s_new = num + offset
            if s_new < 0 or s_new >= size:
                pass
            else:
                if num <= limit:
                    if num > new_dp[s_new][1]:
                        new_dp[s_new][1] = num

            for s in range(size):
                for sign in range(2):
                    if dp[s][sign] == -1:
                        continue
                    p = dp[s][sign]
                    if sign == 0:
                        s_next = s + num
                        p_next = p * num
                        sign_next = 1
                    else:
                        s_next = s - num
                        p_next = p * num
                        sign_next = 0

                    if s_next < 0 or s_next >= size:
                        continue
                    if p_next <= limit:
                        if p_next > new_dp[s_next][sign_next]:
                            new_dp[s_next][sign_next] = p_next
            dp = new_dp

        target = k + offset
        if target < 0 or target >= size:
            return -1
        res = -1
        if dp[target][0] != -1:
            res = max(res, dp[target][0])
        if dp[target][1] != -1:
            res = max(res, dp[target][1])

        return res

class Fenw:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 1)

    def update(self, index, delta):
        while index <= self.n:
            self.tree[index] += delta
            index += index & (-index)

    def query(self, index):
        s = 0
        while index > 0:
            s += self.tree[index]
            index -= index & (-index)
        return s

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        sorted_vals = sorted(set(nums))
        comp = {val: i + 1 for i, val in enumerate(sorted_vals)}
        n_vals = len(sorted_vals)

        freq_tree = Fenw(n_vals)
        sum_tree = Fenw(n_vals)

        def add_val(val):
            idx = comp[val]
            freq_tree.update(idx, 1)
            sum_tree.update(idx, val)

        def remove_val(val):
            idx = comp[val]
            freq_tree.update(idx, -1)
            sum_tree.update(idx, -val)

        def find_median(kth):
            low, high = 1, n_vals
            res = high
            while low <= high:
                mid = (low + high) // 2
                if freq_tree.query(mid) >= kth:
                    res = mid
                    high = mid - 1
                else:
                    low = mid + 1
            return sorted_vals[res - 1]

        window_cost = [0] * (n - x + 1)
        kth = (x + 1) // 2

        for i in range(x):
            add_val(nums[i])

        for i in range(n - x + 1):
            if i > 0:
                remove_val(nums[i - 1])
                add_val(nums[i + x - 1])

            m = find_median(kth)
            idx_m = comp[m]
            left_count = freq_tree.query(idx_m - 1)
            left_sum = sum_tree.query(idx_m - 1)
            right_count = freq_tree.query(n_vals) - freq_tree.query(idx_m)
            right_sum = sum_tree.query(n_vals) - sum_tree.query(idx_m)

            cost = (right_sum - m * right_count) + (m * left_count - left_sum)
            window_cost[i] = cost

        INF = 10**18
        dp = [[INF] * (n + 1) for _ in range(k + 1)]
        for j in range(k + 1):
            dp[j][0] = 0
        for i in range(1, n + 1):
            for j in range(1, k + 1):
                dp[j][i] = dp[j][i - 1]
                if i >= x:
                    prev = i - x
                    cost_here = window_cost[prev]
                    if dp[j - 1][prev] + cost_here < dp[j][i]:
                        dp[j][i] = dp[j - 1][prev] + cost_here

        return dp[k][n]

