class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        INF = float('inf')

        P_nums = [0] * (n + 1)
        P_cost = [0] * (n + 1)
        for i in range(1, n + 1):
            P_nums[i] = P_nums[i - 1] + nums[i - 1]
            P_cost[i] = P_cost[i - 1] + cost[i - 1]

        dp = [[INF] * (n + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for m in range(1, n + 1):
            deque_lines = collections.deque()
            for i in range(m, n + 1):
                j = i - 1
                if dp[j][m - 1] != INF:
                    m_line = -P_cost[j]
                    c_line = dp[j][m - 1]
                    while len(deque_lines) >= 2:
                        m1, c1 = deque_lines[-2]
                        m2, c2 = deque_lines[-1]
                        m3, c3 = m_line, c_line
                        if (c3 - c1) * (m1 - m2) <= (c2 - c1) * (m1 - m3):
                            deque_lines.pop()
                        else:
                            break
                    deque_lines.append((m_line, c_line))

                x = P_nums[i] + k * m
                while len(deque_lines) >= 2:
                    m1, c1 = deque_lines[0]
                    m2, c2 = deque_lines[1]
                    if m1 * x + c1 >= m2 * x + c2:
                        deque_lines.popleft()
                    else:
                        break
                if deque_lines:
                    m0, c0 = deque_lines[0]
                    min_val = m0 * x + c0
                    if min_val != INF:
                        dp[i][m] = x * P_cost[i] + min_val

        return min(dp[n][1:])

