def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1]
    t = data[2]

    # Check feasibility: functional and injective mapping
    mapping = {}
    for i in range(n):
        sc = s[i]
        tc = t[i]
        if sc in mapping:
            if mapping[sc] != tc:
                print(-1)
                return
        else:
            mapping[sc] = tc

    # Check injectivity: the values in mapping must be distinct
    if len(set(mapping.values())) != len(mapping):
        print(-1)
        return

    # Distinct characters in S
    U = set(s)

    # Build graph: for each u in U, if mapping[u] is in U, then edge u -> mapping[u]
    graph = {}
    for u in U:
        v = mapping[u]
        if v in U:
            graph[u] = v
        else:
            graph[u] = None  # No edge within U

    # Build undirected graph for connected components
    undirected_graph = {u: [] for u in U}
    for u in U:
        if u in graph and graph[u] is not None:
            v = graph[u]
            # Add edge u-v in undirected graph
            undirected_graph[u].append(v)
            undirected_graph[v].append(u)

    # Find connected components using BFS on undirected graph
    visited = set()
    components = []
    for node in U:
        if node not in visited:
            comp = []
            queue = deque([node])
            visited.add(node)
            while queue:
                u = queue.popleft()
                comp.append(u)
                for neighbor in undirected_graph[u]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
            components.append(comp)

    total_ops = 0
    for comp in components:
        v = len(comp)
        # Compute in_degree for nodes in this component (only from edges within the component)
        in_degree = {node: 0 for node in comp}
        for u in comp:
            if u in graph and graph[u] is not None:
                # There is an edge u -> graph[u]
                # But only if graph[u] is in the same component (which it is, by construction)
                v_target = graph[u]
                in_degree[v_target] += 1

        # Kahn's algorithm to remove non-cycle nodes
        queue = deque([node for node in comp if in_degree[node] == 0])
        while queue:
            u = queue.popleft()
            if u in graph and graph[u] is not None:
                v_target = graph[u]
                # Only if v_target is in the component (which it is)
                in_degree[v_target] -= 1
                if in_degree[v_target] == 0:
                    queue.append(v_target)

        cycle_nodes = [node for node in comp if in_degree[node] > 0]
        cycle_length = len(cycle_nodes)

        if cycle_length == 0:
            ops = v
        elif cycle_length == 1:
            ops = 0
        else:
            ops = v + 1

        total_ops += ops

    print(total_ops)

