class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def g(n):
            if n == 0:
                return 0
            count = 0
            while n:
                count += 1
                n //= 4
            return count

        def S(n):
            if n == 0:
                return 0
            m = g(n)
            total = 0
            pow4 = 1
            for k in range(1, m):
                count_block = 3 * pow4
                total += k * count_block
                pow4 *= 4
            total += m * (n - pow4 + 1)
            return total

        total_ops = 0
        for l, r in queries:
            max_g = g(r)
            total_g = S(r) - S(l - 1)
            ops = max(max_g, (total_g + 1) // 2)
            total_ops += ops
        return total_ops

