class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n):
            if n == 0:
                return 0
            digits = [int(d) for d in str(n)]
            total = 0
            for s in range(1, 82):
                cache = {}
                def dp(pos, tight, current_sum, current_prod_mod, started):
                    if current_sum > s:
                        return 0
                    if pos == len(digits):
                        if started and current_sum == s and current_prod_mod == 0:
                            return 1
                        return 0
                    state = (pos, tight, current_sum, current_prod_mod, started)
                    if state in cache:
                        return cache[state]
                    upper = digits[pos] if tight else 9
                    res = 0
                    for d in range(0, upper + 1):
                        new_tight = tight and (d == upper)
                        new_started = started or (d != 0)
                        new_sum = current_sum + d
                        if new_sum > s:
                            break
                        if not started:
                            if d == 0:
                                new_prod_mod = 0
                            else:
                                new_prod_mod = d % s
                        else:
                            new_prod_mod = (current_prod_mod * d) % s
                        res += dp(pos + 1, new_tight, new_sum, new_prod_mod, new_started)
                    cache[state] = res
                    return res
                total += dp(0, True, 0, 0, False)
            return total

        return count_up_to(r) - count_up_to(l - 1)

