class SegmentTree:
    def __init__(self, n):
        self.size = 1
        while self.size < n:
            self.size *= 2
        self.data = [0] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)

    def push(self, node):
        if self.lazy[node] != 0:
            for child in [2*node, 2*node+1]:
                self.data[child] += self.lazy[node]
                self.lazy[child] += self.lazy[node]
            self.lazy[node] = 0

    def update(self, l, r, val, node, node_l, node_r):
        if r < node_l or l > node_r:
            return
        if l <= node_l and node_r <= r:
            self.data[node] += val
            self.lazy[node] += val
            return
        self.push(node)
        mid = (node_l + node_r) // 2
        self.update(l, r, val, 2*node, node_l, mid)
        self.update(l, r, val, 2*node+1, mid+1, node_r)
        self.data[node] = max(self.data[2*node], self.data[2*node+1])

    def update_range(self, l, r, val):
        if l > r:
            return
        self.update(l, r, val, 1, 0, self.size-1)

    def query(self, l, r, node, node_l, node_r):
        if r < node_l or l > node_r:
            return -10**18
        if l <= node_l and node_r <= r:
            return self.data[node]
        self.push(node)
        mid = (node_l + node_r) // 2
        left_val = self.query(l, r, 2*node, node_l, mid)
        right_val = self.query(l, r, 2*node+1, mid+1, node_r)
        return max(left_val, right_val)

    def query_range(self, l, r):
        if l > r:
            return -10**18
        return self.query(l, r, 1, 0, self.size-1)

