class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total_len = n + m - 1
        res = [None] * total_len

        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if res[pos] is not None and res[pos] != str2[j]:
                        return ""
                    res[pos] = str2[j]

        for k in range(total_len):
            if res[k] is None:
                res[k] = 'a'

        forced = [False] * total_len
        for i in range(n):
            if str1[i] == 'T':
                for j in range(i, i + m):
                    forced[j] = True

        for i in range(n):
            if str1[i] == 'F':
                if res[i:i+m] == list(str2):
                    j = i + m - 1
                    found = False
                    while j >= i:
                        if not forced[j]:
                            c = 'a'
                            if c == str2[j - i]:
                                c = 'b'
                            res[j] = c
                            found = True
                            break
                        j -= 1
                    if not found:
                        return ""

        return "".join(res)

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odd_count = (n + 1) // 2
        even_count = n // 2

        dp = [[[0] * 2 for _ in range(even_count + 1)] for _ in range(odd_count + 1)]
        dp[0][0][0] = 1
        dp[0][0][1] = 1

        for i in range(odd_count + 1):
            for j in range(even_count + 1):
                if i == 0 and j == 0:
                    continue
                if j > 0:
                    dp[i][j][0] = j * dp[i][j-1][1]
                if i > 0:
                    dp[i][j][1] = i * dp[i-1][j][0]

        total = 0
        if odd_count > 0:
            total += odd_count * dp[odd_count - 1][even_count][0]
        if even_count > 0:
            total += even_count * dp[odd_count][even_count - 1][1]

        if k > total:
            return []

        rem_odd = odd_count
        rem_even = even_count
        used = [False] * (n + 1)
        result = []

        for pos in range(n):
            if pos == 0:
