                        result.append(x)
                        if x % 2 == 1:
                            rem_odd -= 1
                        else:
                            rem_even -= 1
                        break
                    else:
                        k -= count
            else:
                last_parity = result[-1] % 2
                required_parity = 1 - last_parity
                for x in range(1, n + 1):
                    if used[x]:
                        continue
                    if x % 2 != required_parity:
                        continue

                    if x % 2 == 1:
                        count = dp[rem_odd - 1][rem_even][0] if rem_odd > 0 else 0
                    else:
                        count = dp[rem_odd][rem_even - 1][1] if rem_even > 0 else 0

                    if k <= count:
