class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        if n == 0 or m == 0:
            return 0

        dirs = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
        clockwise = [1, 3, 0, 2]

        dp_end = [[[0] * m for _ in range(n)] for _ in range(4)]

        for d in range(4):
            dr, dc = dirs[d]
            for i in range(n):
                for j in range(m):
                    pi, pj = i - dr, j - dc
                    if pi < 0 or pi >= n or pj < 0 or pj >= m:
                        if grid[i][j] == 1:
                            dp_end[d][i][j] = 1
                        else:
                            dp_end[d][i][j] = 0
                    else:
                        if dp_end[d][pi][pj] == 0:
                            dp_end[d][i][j] = 0
                        else:
                            L = dp_end[d][pi][pj]
                            expected = 2 if (L % 2 == 1) else 0
                            if grid[i][j] == expected:
                                dp_end[d][i][j] = L + 1
                            else:
                                dp_end[d][i][j] = 0

        out_len = [[[[0, 0] for _ in range(m)] for _ in range(n)] for _ in range(4)]

        for d in range(4):
            dr, dc = dirs[d]
            for i in range(n-1, -1, -1):
                for j in range(m-1, -1, -1):
                    ni, nj = i + dr, j + dc
                    if ni < 0 or ni >= n or nj < 0 or nj >= m:
                        out_len[d][i][j][0] = 1
                        out_len[d][i][j][1] = 1
                    else:
                        if grid[ni][nj] == 2:
                            out_len[d][i][j][0] = 1 + out_len[d][ni][nj][1]
                        else:
                            out_len[d][i][j][0] = 1
                        if grid[ni][nj] == 0:
                            out_len[d][i][j][1] = 1 + out_len[d][ni][nj][0]
                        else:
                            out_len[d][i][j][1] = 1

        ans = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    for d in range(4):
                        l = out_len[d][i][j][0]
                        if l > ans:
                            ans = l

        for i in range(n):
            for j in range(m):
                for d1 in range(4):
                    L_in = dp_end[d1][i][j]
                    if L_in < 2:
                        continue
                    d2 = clockwise[d1]
                    expected_next = 2 if (L_in % 2 == 1) else 0
                    state = 0 if expected_next == 2 else 1
                    L_out = out_len[d2][i][j][state]
                    total = L_in + L_out - 1
                    if total > ans:
                        ans = total

        return ans

