class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        count = 0
        # Limit for backward iteration
        LIMIT = 100
        for j in range(n):
            d = int(s[j])
            if d == 0:
                continue
            rem = 0
