class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        INF = 10**9

        dp = [[[INF] * 4 for _ in range(26)] for _ in range(n+1)]

        for c in range(26):
            cost0 = abs(ord(caption[0]) - (ord('a') + c))
            dp[1][c][1] = cost0

        for i in range(1, n):
            for c in range(26):
                add_cost = abs(ord(caption[i]) - (ord('a') + c))
                for l_prev in range(1, 4):
                    if dp[i][c][l_prev] != INF:
                        new_l = min(l_prev + 1, 3)
                        new_cost = dp[i][c][l_prev] + add_cost
                        if new_cost < dp[i+1][c][new_l]:
                            dp[i+1][c][new_l] = new_cost
                for prev_c in range(26):
                    if prev_c == c:
                        continue
                    if dp[i][prev_c][3] != INF:
                        new_l = 1
                        new_cost = dp[i][prev_c][3] + add_cost
                        if new_cost < dp[i+1][c][1]:
                            dp[i+1][c][1] = new_cost

        min_total = INF
        for c in range(26):
            if dp[n][c][3] < min_total:
                min_total = dp[n][c][3]

        if min_total == INF:
            return ""

        dp_back = [[[INF] * 4 for _ in range(26)] for _ in range(n+1)]
        for c in range(26):
            for l in range(1, 4):
                dp_back[n][c][l] = 0

        for i in range(n-1, -1, -1):
            for c_prev in range(26):
                for l_prev in range(1, 4):
                    if dp_back[i+1] is not None:
                        for c_curr in range(26):
                            add_cost = abs(ord(caption[i]) - (ord('a') + c_curr))
                            if c_curr == c_prev:
                                new_l = min(l_prev + 1, 3)
                                new_c = c_curr
                            else:
                                if l_prev == 3:
                                    new_l = 1
                                    new_c = c_curr
                                else:
                                    continue
                            if dp_back[i+1][new_c][new_l] == INF:
                                continue
                            total = add_cost + dp_back[i+1][new_c][new_l]
                            if total < dp_back[i][c_prev][l_prev]:
                                dp_back[i][c_prev][l_prev] = total

        result = []
        cost_so_far = 0
        prev_c = None
        prev_l = 0

        for i in range(n):
            for c in range(26):
                add_cost = abs(ord(caption[i]) - (ord('a') + c))
                if i == 0:
                    new_l = 1
                    new_c = c
                    valid = True
                else:
                    if c == prev_c:
                        new_l = min(prev_l + 1, 3)
                        new_c = c
                        valid = True
                    else:
                        if prev_l == 3:
                            new_l = 1
                            new_c = c
                            valid = True
                        else:
                            valid = False
                if not valid:
                    continue
                if dp[i+1][new_c][new_l] != cost_so_far + add_cost:
                    continue
                if cost_so_far + add_cost + dp_back[i+1][new_c][new_l] != min_total:
                    continue
                result.append(chr(ord('a') + c))
                cost_so_far += add_cost
                prev_c = new_c
                prev_l = new_l
                break

        return ''.join(result)

