class Solution:
    MOD = 10**9 + 7
    max_n = 100001
    fact = [1] * max_n
    inv_fact = [1] * max_n
    precomputed = False

    @classmethod
    def precompute(cls):
        if cls.precomputed:
            return
        for i in range(1, cls.max_n):
            cls.fact[i] = (cls.fact[i-1] * i) % cls.MOD
        cls.inv_fact[cls.max_n - 1] = pow(cls.fact[cls.max_n - 1], cls.MOD - 2, cls.MOD)
        for i in range(cls.max_n - 2, -1, -1):
            cls.inv_fact[i] = (cls.inv_fact[i+1] * (i + 1)) % cls.MOD
        cls.precomputed = True

    def distanceSum(self, m: int, n: int, k: int) -> int:
        if not Solution.precomputed:
            Solution.precompute()

        mod = self.MOD
        N = m * n
        term_x = m * (m - 1) * (m + 1) // 6
        term_y = n * (n - 1) * (n + 1) // 6

        sum_x = (n * n) % mod * (term_x % mod) % mod
        sum_y = (m * m) % mod * (term_y % mod) % mod
        total_base = (sum_x + sum_y) % mod

        r = k - 2
        n_val = N - 2
        if r < 0 or r > n_val:
            nCr = 0
        else:
            nCr = Solution.fact[n_val] * Solution.inv_fact[r] % mod * Solution.inv_fact[n_val - r] % mod

        return (nCr * total_base) % mod

