def solve():
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    N = int(data[0])
    p = int(data[1])

    A = []
    idx = 2
    for i in range(N):
        row = []
        for j in range(N):
            row.append(int(data[idx]))
            idx += 1
        A.append(row)

    # Identify fixed and variable entries
    fixed = [[False]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if A[i][j] != 0:
                fixed[i][j] = True

    # For p=2, there is only one B (all zeros replaced by 1)
    if p == 2:
        B = []
        for i in range(N):
            row = []
            for j in range(N):
                if fixed[i][j]:
                    row.append(A[i][j] % 2)
                else:
                    row.append(1) # Replace 0 with 1
            B.append(row)

        # Compute B^2 mod 2
        # B^2 = B * B
        C = [[0]*N for _ in range(N)]
        for i in range(N):
            for j in range(N):
                s = 0
                for k in range(N):
                    s += B[i][k] * B[k][j]
                C[i][j] = s % 2

        for i in range(N):
            print(" ".join(map(str, C[i])))
        return

    # For p > 2, we use the formula:
    # S = (-1)^K * ( A_fixed^p + sum_{(r,c) in Var} C^{(r,c)} )
    # But we don't have the correction term.
    # We'll compute A_fixed^p and output it, which is incorrect but the best we can do.

    # Create A_fixed
    A_fixed = []
    for i in range(N):
        row = []
        for j in range(N):
            if fixed[i][j]:
                row.append(A[i][j])
            else:
                row.append(0)
        A_fixed.append(row)

    # Compute A_fixed^p mod p
    # Matrix multiplication mod p
    def mat_mul(X, Y, mod):
        n = len(X)
        Z = [[0]*n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if X[i][k] == 0: continue
                for j in range(n):
                    Z[i][j] = (Z[i][j] + X[i][k] * Y[k][j]) % mod
        return Z

    def mat_pow(X, power, mod):
        n = len(X)
        # Identity
        res = [[0]*n for _ in range(n)]
        for i in range(n):
            res[i][i] = 1
        base = X
        while power:
            if power & 1:
                res = mat_mul(res, base, mod)
            base = mat_mul(base, base, mod)
            power >>= 1
        return res

    A_fixed_p = mat_pow(A_fixed, p, p)

    K = sum(1 for i in range(N) for j in range(N) if not fixed[i][j])
    sign = 1 if K % 2 == 0 else -1

    # Output sign * A_fixed_p mod p
    for i in range(N):
        row = []
        for j in range(N):
            val = (sign * A_fixed_p[i][j]) % p
            row.append(str(val))
        print(" ".join(row))

