class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        count = 0
        l = 0
        for r in range(n):
            current_cost = 0
            prev = nums[l]
            for i in range(l + 1, r + 1):
                if nums[i] < prev:
                    current_cost += prev - nums[i]
                else:
                    prev = nums[i]
                if current_cost > k:
                    break
            while current_cost > k and l < r:
                l += 1
                current_cost = 0
                prev = nums[l]
                for i in range(l + 1, r + 1):
                    if nums[i] < prev:
                        current_cost += prev - nums[i]
                    else:
                        prev = nums[i]
                    if current_cost > k:
                        break
            count += (r - l + 1)
        return count

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        if n == 0:
            return []

        # Create a list of intervals with original indices
        sorted_intervals = []
        for idx, (l, r, w) in enumerate(intervals):
            sorted_intervals.append((l, r, w, idx))

        # Sort by start time, then by end time, then by weight descending, then by original index ascending
        # Actually, for the purpose of non-overlapping, sorting by start time is primary.
        sorted_intervals.sort(key=lambda x: (x[0], x[1], -x[2], x[3]))

        # Extract start times for binary search
        starts = [x[0] for x in sorted_intervals]

        # Precompute next_idx: for each interval i, the smallest j such that sorted_intervals[j][0] > sorted_intervals[i][1]
        import bisect
        next_idx = [n] * n
        for i in range(n):
            # We need the first interval with start > sorted_intervals[i][1]
            pos = bisect.bisect_right(starts, sorted_intervals[i][1])
            if pos < n:
                next_idx[i] = pos
            else:
                next_idx[i] = n

        # best[k][i] will store a tuple (total_weight, list_of_original_indices) for choosing k intervals from sorted_intervals[i:]
        # k from 1 to 4, i from 0 to n (n is out of bound, represents empty)
        best = [[None] * (n + 1) for _ in range(5)]

        # Initialize best[k][n] as None for all k
        # Compute for k=1
        for i in range(n - 1, -1, -1):
            w, idx_orig = sorted_intervals[i][2], sorted_intervals[i][3]
            # Compare with best[1][i+1]
            if i + 1 <= n - 1 and best[1][i+1] is not None:
                nw, nidx = best[1][i+1]
                if w > nw:
                    best[1][i] = (w, [idx_orig])
                elif w == nw:
                    if idx_orig < nidx[0]:
                        best[1][i] = (w, [idx_orig])
                    else:
                        best[1][i] = best[1][i+1]
                else:
                    best[1][i] = best[1][i+1]
            else:
                best[1][i] = (w, [idx_orig])

        # Compute for k=2,3,4
        for k in range(2, 5):
            for i in range(n - 1, -1, -1):
                # Option 1: pick interval i, then k-1 intervals from next_idx[i]
                ni = next_idx[i]
                w1 = -1
                idx1 = None
                if ni < n and best[k-1][ni] is not None:
                    w1 = sorted_intervals[i][2] + best[k-1][ni][0]
                    # Combine the current index with the indices from best[k-1][ni]
                    idx1 = sorted([sorted_intervals[i][3]] + best[k-1][ni][1])

                # Option 2: skip interval i, take best[k][i+1]
                opt2 = best[k][i+1]

                # Compare option1 and option2
                if opt2 is None:
                    if w1 != -1:
                        best[k][i] = (w1, idx1)
                    else:
                        best[k][i] = None
                else:
                    if w1 == -1:
                        best[k][i] = opt2
                    else:
                        if w1 > opt2[0]:
                            best[k][i] = (w1, idx1)
                        elif w1 < opt2[0]:
                            best[k][i] = opt2
                        else:
                            # Compare lexicographically the index lists
                            if idx1 < opt2[1]:
                                best[k][i] = (w1, idx1)
                            else:
                                best[k][i] = opt2

        # Now, the answer is the best among best[1][0], best[2][0], best[3][0], best[4][0]
        best_overall = None
        for k in range(1, 5):
            res = best[k][0]
            if res is None:
                continue
            if best_overall is None:
                best_overall = res
            else:
                # Compare: higher weight is better, then lexicographically smaller index list
                if res[0] > best_overall[0]:
                    best_overall = res
                elif res[0] == best_overall[0]:
                    if res[1] < best_overall[1]:
                        best_overall = res

        return best_overall[1] if best_overall else []

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # Build segment tree
        size = 1
        while size < n:
            size *= 2
        tree = [None] * (2 * size)

        def build(node, start, end):
            if start == end:
                val = nums[start]
                tree[node] = (val, val, val, val)
            else:
                mid = (start + end) // 2
                left_node = 2 * node
                right_node = 2 * node + 1
                build(left_node, start, mid)
                build(right_node, mid + 1, end)

                left_val = tree[left_node]
                right_val = tree[right_node]

                total = left_val[3] + right_val[3]
                prefix = max(left_val[1], left_val[3] + right_val[1])
                suffix = max(right_val[2], right_val[3] + left_val[2])
                max_sum = max(left_val[0], right_val[0], left_val[2] + right_val[1])
                tree[node] = (max_sum, prefix, suffix, total)

        build(1, 0, n - 1)

        def query(node, start, end, l, r):
            if r < start or end < l:
                return (-10**18, -10**18, -10**18, -10**18)
            if l <= start and end <= r:
                return tree[node]
            mid = (start + end) // 2
            left_res = query(2 * node, start, mid, l, r)
            right_res = query(2 * node + 1, mid + 1, end, l, r)

            if left_res[3] == -10**18:
                return right_res
            if right_res[3] == -10**18:
                return left_res

            total = left_res[3] + right_res[3]
            prefix = max(left_res[1], left_res[3] + right_res[1])
            suffix = max(right_res[2], right_res[3] + left_res[2])
            max_sum = max(left_res[0], right_res[0], left_res[2] + right_res[1])
            return (max_sum, prefix, suffix, total)

        # Get the original max subarray sum
        orig_max = query(1, 0, n - 1, 0, n - 1)[0]
        ans = orig_max

        # Group indices by value
        from collections import defaultdict
        pos_map = defaultdict(list)
        for i, num in enumerate(nums):
            pos_map[num].append(i)

        # For each distinct number, process the segments
        for x, positions in pos_map.items():
            segments = []
            if positions[0] > 0:
                segments.append((0, positions[0] - 1))
            for j in range(1, len(positions)):
                if positions[j] - positions[j-1] > 1:
                    segments.append((positions[j-1] + 1, positions[j] - 1))
            if positions[-1] < n - 1:
                segments.append((positions[-1] + 1, n - 1))

            for (l, r) in segments:
                if l <= r:
                    res = query(1, 0, n - 1, l, r)
                    if res[0] > ans:
                        ans = res[0]

        return ans

