class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # Helper function to check if it's possible to have max run length <= k with at most numOps flips
        def can_achieve(k: int) -> bool:
            total_flips = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                L = j - i
                total_flips += L // (k + 1)
                i = j
                # Early termination if flips exceed numOps
                if total_flips > numOps:
                    return False
            return total_flips <= numOps

        # Binary search for the minimum k
        low, high = 1, n
        ans = n
        while low <= high:
            mid = (low + high) // 2
            if can_achieve(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans

class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        freq = [0] * 26
        for char in s:
            freq[ord(char) - ord('a')] += 1

        indices_freq = sorted([(freq[i], i) for i in range(26)], key=lambda x: x[0], reverse=True)

        k_configs = []
        for k in range(1, 27):
            top_k = indices_freq[:k]
            chosen_indices = set(idx for (f, idx) in top_k)
            chosen_freqs = [f for (f, idx) in top_k]
            sum_chosen = sum(chosen_freqs)
            k_configs.append((chosen_indices, chosen_freqs, sum_chosen))

        ans = float('inf')

        for k in range(1, 27):
            chosen_indices, chosen_freqs, sum_chosen = k_configs[k-1]
            for f in range(1, n + 1):
                base_cost = n - sum_chosen + sum(abs(c - f) for c in chosen_freqs)
                if base_cost >= ans:
                    continue
                savings = 0
                for i in range(25):
                    if i in chosen_indices and (i + 1) in chosen_indices:
                        excess = max(0, freq[i] - f)
                        deficit_next = max(0, f - freq[i+1])
                        savings += min(excess, deficit_next)
                cost = base_cost - savings
                if cost < ans:
                    ans = cost
        return ans

