class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Filter out numbers greater than threshold as they cannot form any edge
        # But note: they still form their own component.
        # We'll handle them separately.

        # Create a set for O(1) lookups
        num_set = set(nums)

        # Initialize Union-Find for numbers that are <= threshold
        # We only need to track numbers that are in nums and <= threshold
        # But to make indexing easy, we can use a dictionary or an array for indices 1..threshold
        # However, since numbers can be up to 10^9, but we only care about those <= threshold (<=2e5),
        # we can create an array for 0..threshold.

        # Let's create a parent array for 0 to threshold. 
        # We will only use indices that are present in nums and <= threshold.
        parent = list(range(threshold + 1))
        rank = [0] * (threshold + 1)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # path compression
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            # union by rank
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # For each number x in nums that is <= threshold, 
        # connect it with its multiples that are also in nums and <= threshold.
        for x in nums:
            if x > threshold:
                continue
            # Check multiples: 2*x, 3*x, ... up to threshold
            m = 2 * x
            while m <= threshold:
                if m in num_set:
                    union(x, m)
                m += x

        # Count the number of connected components among numbers <= threshold
        # Each number in nums that is <= threshold is a node.
        # The number of components is the number of distinct roots for these nodes.
        components = 0
        for x in nums:
            if x <= threshold:
                if find(x) == x:
                    components += 1
            else:
                # Numbers greater than threshold form their own component
                components += 1

        return components
